<?php require '_guard.php';if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';$s=$pdo->prepare("SELECT * FROM payments WHERE payment_id=?");$s->execute([$id]);$p=$s->fetch();if($p&&$action==='verify'&&$p['status']==='payment_review'){$pdo->prepare("UPDATE payments SET status='verified',verified_at=NOW() WHERE payment_id=?")->execute([$id]);$pdo->prepare("UPDATE registrations SET status='confirmed' WHERE registration_id=?")->execute([$p['registration_id']]);flash('success','Demo payment manually marked verified; registration confirmed.');}elseif($p&&$action==='fail'){$pdo->prepare("UPDATE payments SET status='failed' WHERE payment_id=?")->execute([$id]);$pdo->prepare("UPDATE registrations SET status='pending_payment' WHERE registration_id=?")->execute([$p['registration_id']]);}go('payments.php');}$rows=$pdo->query("SELECT p.*,r.registration_code,r.team_name,t.name tn FROM payments p JOIN registrations r ON r.registration_id=p.registration_id JOIN tournaments t ON t.tournament_id=r.tournament_id ORDER BY p.created_at DESC")->fetchAll();$pageTitle='Payment review';require '../includes/header.php';?><section class="page-hero compact"><div class="eyebrow">ADMIN / PAYMENT OPERATIONS</div><h1>PAYMENT <span>REVIEW.</span></h1><p>Manual verification demo — not connected to a bank or payment gateway.</p></section><?php require 'nav.php';?><section class="box section"><div class="table-responsive"><table class="table arena-table"><thead><tr><th>TEAM / CODE</th><th>TOURNAMENT</th><th>AMOUNT</th><th>TRANSACTION REF</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['team_name'])?></b><small><?=e($r['registration_code'])?></small></td><td><?=e($r['tn'])?></td><td>₹<?=number_format((float)$r['amount'],2)?></td><td><?=e($r['transaction_reference']?:'—')?></td><td><?=e(str_replace('_',' ',$r['status']))?></td><td><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="id" value="<?=(int)$r['payment_id']?>"><button name="action" value="verify" class="btn btn-sm btn-success" <?=$r['status']!=='payment_review'?'disabled':''?>>Verify</button><button name="action" value="fail" class="btn btn-sm btn-outline-danger">Failed</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php require '../includes/footer.php';?>
